from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
MANAGER = (ROOT / 'app/src/main/java/vn/kholinhkien/BackupManager.kt').read_text()
INSPECTOR = (ROOT / 'app/src/main/java/vn/kholinhkien/BackupArchiveInspector.kt').read_text()
RESTORE = (ROOT / 'app/src/main/java/vn/kholinhkien/ZipRestore.kt').read_text()
checks = []
def check(name, condition): checks.append((name, bool(condition)))
check('MediaStore backup is re-opened after ZIP stream completion', 'resolver.openInputStream(uri)' in MANAGER and 'BackupArchiveInspector.verify(readBack, ownerId)' in MANAGER)
check('MediaStore backup remains pending until read-back validation succeeds', MANAGER.index('BackupArchiveInspector.verify(readBack, ownerId)') < MANAGER.index('put(MediaStore.MediaColumns.IS_PENDING, 0)'))
check('Android 8/9 partial ZIP is validated before atomic rename', MANAGER.index('BackupArchiveInspector.verify(it, ownerId)') < MANAGER.index('partial.renameTo(target)'))
check('failed read-back validation follows existing cleanup path', 'resolver.delete(uri, null, null)' in MANAGER and 'partial.delete()' in MANAGER)
check('verifier reads the closed ZIP stream entry-by-entry', 'ZipInputStream(input.buffered()).use' in INSPECTOR)
check('verifier rejects excessive entry count', '++entryCount <= MAX_ENTRIES' in INSPECTOR)
check('verifier rejects unsafe paths and duplicate entries', 'name.split("/").none { it == ".." || it.isBlank() }' in INSPECTOR and 'seen.add(name)' in INSPECTOR)
check('verifier restricts entry names to manifest, JSONL and photos', 'name == "manifest.json" || name == "parts.jsonl"' in INSPECTOR and 'name == "movements.jsonl" || isPhoto' in INSPECTOR)
check('verifier enforces per-entry and aggregate uncompressed size bounds', 'entryBytes <= limit' in INSPECTOR and 'totalBytes <= MAX_TOTAL_BYTES' in INSPECTOR)
check('verifier requires manifest and both data payloads', '"manifest.json" in seen && "parts.jsonl" in seen && "movements.jsonl" in seen' in INSPECTOR)
check('verifier checks archive version and exact owner', 'manifest.optInt("version", -1) == 2' in INSPECTOR and 'ownerId == expectedOwnerId' in INSPECTOR)
check('verifier checks part and movement record counts', 'partsLines == expectedParts && movementLines == expectedMovements' in INSPECTOR)
check('verifier requires exact SHA-256 name set', 'checksumNames == seen.filter { it != "manifest.json" }.toSet()' in INSPECTOR)
check('verifier hashes exact decompressed entry bytes and compares SHA-256', 'digest.update(buffer, 0, count)' in INSPECTOR and 'actual.equals(expected, true)' in INSPECTOR)
check('restore retains its independent checksum and payload validation', 'sha256(File(stage, name))' in RESTORE and 'checksumNames == expectedNames' in RESTORE)
for name, ok in checks: print(('PASS' if ok else 'FAIL') + ' ' + name)
print(f'{sum(ok for _, ok in checks)}/{len(checks)} PASS')
if not all(ok for _, ok in checks): raise SystemExit(1)
